css:
.execprogsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1c2a3a;
    background: linear-gradient(165deg, #f3f1ea 0%, #ece7da 100%);
    border-radius: 18px;
}

.execprogsim-container * {
    box-sizing: border-box;
}

.execprogsim-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #10243d 0%, #1b3a5e 55%, #244a73 100%);
    color: #f6f2e8;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 12px 32px rgba(16, 36, 61, 0.34);
    border-bottom: 3px solid #c9a227;
}

.execprogsim-header h1 {
    margin: 10px 0 12px;
    font-size: 2.35rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.execprogsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.3px;
    font-weight: 700;
    color: #f0d98a;
    background: rgba(201, 162, 39, 0.16);
    padding: 5px 14px;
    border-radius: 999px;
}

.execprogsim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #dbe5f0;
}

.execprogsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #2c4868;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.execprogsim-period-counter #currentDay,
.execprogsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #10243d;
}

.execprogsim-round-name {
    background: #e7dcbc;
    color: #6b4e0c;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.execprogsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #9a3412;
    background: #f6e4da;
    padding: 4px 12px;
    border-radius: 999px;
}

.execprogsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.execprogsim-status-card {
    background: #fffdf8;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #e4dcc6;
    box-shadow: 0 4px 14px rgba(16, 36, 61, 0.07);
    border-top: 4px solid #244a73;
}

.execprogsim-card-margin { border-top-color: #1d6b4f; }
.execprogsim-card-outcome { border-top-color: #2f6fb0; }
.execprogsim-card-trust { border-top-color: #c9a227; }
.execprogsim-card-faculty { border-top-color: #7a4ea8; }

.execprogsim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6e7c8c;
}

.execprogsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #10243d;
}

.execprogsim-card-margin .execprogsim-value { color: #1d6b4f; }
.execprogsim-card-outcome .execprogsim-value { color: #2f6fb0; }
.execprogsim-card-trust .execprogsim-value { color: #b08a13; }
.execprogsim-card-faculty .execprogsim-value { color: #7a4ea8; }

.execprogsim-sublabel {
    font-size: 0.76rem;
    color: #7d8a99;
    line-height: 1.35;
}

.execprogsim-margin-fail .execprogsim-value { color: #c0392b; }
.execprogsim-margin-target .execprogsim-value { color: #1d6b4f; }

.execprogsim-faculty-over { border-top-color: #c0392b; }
.execprogsim-faculty-over .execprogsim-value { color: #c0392b; }

.execprogsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #10243d;
    color: #f3eddc;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
    border-left: 4px solid #c9a227;
}

.execprogsim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #f0d98a;
}

.execprogsim-briefing {
    display: flex;
    gap: 14px;
    background: #fffdf8;
    border-left: 5px solid #c9a227;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(16, 36, 61, 0.06);
}

.execprogsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.execprogsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #10243d;
    margin-bottom: 6px;
}

.execprogsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #33465c;
}

.execprogsim-briefing-text strong { color: #1d6b4f; }
.execprogsim-briefing-text em { color: #9a3412; font-style: italic; }

.execprogsim-controls {
    background: #fffdf8;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #e4dcc6;
    box-shadow: 0 4px 14px rgba(16, 36, 61, 0.07);
}

.execprogsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #10243d;
    border-bottom: 2px solid #ece4ce;
    padding-bottom: 8px;
}

.execprogsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #24364b;
    margin: 14px 0 6px;
}

.execprogsim-container select,
.execprogsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #cdbf9a;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #fbf8ef;
    color: #1c2a3a;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.execprogsim-container select:focus,
.execprogsim-container input[type="number"]:focus {
    outline: none;
    border-color: #c9a227;
    box-shadow: 0 0 0 3px rgba(201, 162, 39, 0.18);
}

.execprogsim-container select option {
    background-color: #ffffff;
    color: #1c2a3a;
}

.execprogsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #244a73;
}

.execprogsim-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #2c4868;
    margin-top: 4px;
}

.execprogsim-range-readout span:last-child {
    color: #1d6b4f;
    font-weight: 800;
}

.execprogsim-hint {
    font-size: 0.8rem;
    color: #7d8a99;
    margin-top: 4px;
    line-height: 1.4;
}

.execprogsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.execprogsim-container .btn-primary {
    background: linear-gradient(135deg, #1b3a5e 0%, #c9a227 130%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    color: #fffdf8;
    box-shadow: 0 6px 16px rgba(27, 58, 94, 0.30);
}

.execprogsim-container .btn-primary:hover {
    filter: brightness(1.07);
}

.execprogsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #cdbf9a;
    color: #6e7c8c;
}

.execprogsim-coach {
    background: #10243d;
    color: #eaf0f7;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(16, 36, 61, 0.24);
    border-left: 4px solid #c9a227;
}

.execprogsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #f0d98a;
    margin-bottom: 8px;
}

.execprogsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.execprogsim-coach-body strong { color: #f0d98a; }
.execprogsim-coach-body em { color: #f3b58c; font-style: italic; }

.execprogsim-history,
.execprogsim-chart {
    background: #fffdf8;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #e4dcc6;
    box-shadow: 0 4px 14px rgba(16, 36, 61, 0.07);
}

.execprogsim-history h3,
.execprogsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #10243d;
}

.execprogsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #24364b;
}

.execprogsim-container table#usfHistoryTable th {
    background: #f1ead4;
    color: #10243d;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #e0d4b0;
}

.execprogsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #efe9d8;
}

.execprogsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf6ec;
}

.execprogsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .execprogsim-container {
        padding: 14px;
    }
    .execprogsim-header h1 {
        font-size: 1.7rem;
    }
    .execprogsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .execprogsim-value {
        font-size: 2rem;
    }
    .execprogsim-clock {
        margin-left: 0;
    }
    .execprogsim-period-counter {
        font-size: 0.88rem;
    }
    .execprogsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .execprogsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

