(function() {
    'use strict';

    class ExecProgAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Building the Exec Program`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card.
            this.CONTRACT_VALUE = 1600;       // EUR 1.6M, in thousands
            this.TARGET_MARGIN = 22;          // % operating margin target
            this.MARGIN_FLOOR = 10;           // below this the deal is value-destroying
            this.MARQUEE_AVAILABLE = 3;       // 3 of 7 marquee faculty free in the window
            this.MARQUEE_TOTAL = 7;
            this.PRICE_CEILING = 1700;        // procurement-implied ceiling (EUR k)
            // Program P&L: fixed delivery + overhead base (EUR k) the program carries before
            // faculty and format. Calibrated so the textbook play (3 marquee + hybrid, full
            // €1.6M price) lands right on the 22% margin target.
            this.OVERHEAD_BASE = 700;
            this.START_PRICE = 1600;          // contract value until the team prices in R3

            // Concept truths.
            this.TRUE_DESIGN = `backward`;
            this.TRUE_CONCESSION = `descope`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    margin: this.TARGET_MARGIN,
                    outcome: 20,
                    trust: 45,
                    facultyDeliverable: this.MARQUEE_AVAILABLE,
                    marqueeProposed: this.MARQUEE_AVAILABLE,
                    price: this.START_PRICE,
                    budgetUsed: this.OVERHEAD_BASE,
                    marginMissed: false,
                    overPromised: false,
                    marginHistory: [this.TARGET_MARGIN],
                    outcomeHistory: [20],
                    trustHistory: [45],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    design: `hybrid`,
                    contradiction: `format`,
                    rigor: 50,
                    marquee: 3,
                    format: `hybrid`,
                    application: 40,
                    price: 1600,
                    concession: `hold`,
                    delivery: `lean`,
                    cancel: `swap`,
                    clash: `push`,
                    evidence: `satisfaction`,
                    defend: 60
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const ds = document.getElementById(`designInput`);
                const co = document.getElementById(`contradictionInput`);
                const ri = document.getElementById(`rigorInput`);
                if (ds) decisions.design = ds.value;
                if (co) decisions.contradiction = co.value;
                if (ri) decisions.rigor = parseInt(ri.value, 10);
                if (!Number.isFinite(decisions.rigor) || decisions.rigor < 0 || decisions.rigor > 100) {
                    warn(`warn_rigor_range`); return false;
                }
            } else if (round === 2) {
                const mq = document.getElementById(`marqueeInput`);
                const fm = document.getElementById(`formatInput`);
                const ap = document.getElementById(`applicationInput`);
                if (mq) decisions.marquee = parseInt(mq.value, 10);
                if (fm) decisions.format = fm.value;
                if (ap) decisions.application = parseInt(ap.value, 10);
                if (!Number.isFinite(decisions.marquee) || decisions.marquee < 0 || decisions.marquee > this.MARQUEE_TOTAL) {
                    warn(`warn_marquee_range`); return false;
                }
                if (!Number.isFinite(decisions.application) || decisions.application < 0 || decisions.application > 100) {
                    warn(`warn_application_range`); return false;
                }
            } else if (round === 3) {
                const pr = document.getElementById(`priceInput`);
                const cn = document.getElementById(`concessionInput`);
                const dl = document.getElementById(`deliveryInput`);
                if (pr) decisions.price = parseInt(pr.value, 10);
                if (cn) decisions.concession = cn.value;
                if (dl) decisions.delivery = dl.value;
                if (!Number.isFinite(decisions.price) || decisions.price < 1000 || decisions.price > 1900) {
                    warn(`warn_price_range`); return false;
                }
            } else if (round === 4) {
                const ca = document.getElementById(`cancelInput`);
                const cl = document.getElementById(`clashInput`);
                const ev = document.getElementById(`evidenceInput`);
                const df = document.getElementById(`defendInput`);
                if (ca) decisions.cancel = ca.value;
                if (cl) decisions.clash = cl.value;
                if (ev) decisions.evidence = ev.value;
                if (df) decisions.defend = parseInt(df.value, 10);
                if (!Number.isFinite(decisions.defend) || decisions.defend < 0 || decisions.defend > 100) {
                    warn(`warn_defend_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let outcomeDelta = 0, trustDelta = 0;
            let spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;
            const prevMargin = ds.margin;

            if (round === 1) {
                // Decode the brief — backward, outcome-led design beats content-first and catalogue reuse.
                switch (d.design) {
                    case `backward`: outcomeDelta += 14; trustDelta += 5; coachKey = `coach_r1_backward`; break;
                    case `hybrid`: outcomeDelta += 6; trustDelta += 2; coachKey = `coach_r1_hybrid`; break;
                    case `content`: outcomeDelta -= 7; trustDelta -= 2; coachKey = `coach_r1_content`; break;
                    case `reuse`: outcomeDelta -= 10; trustDelta -= 7; coachKey = `coach_r1_reuse`; break;
                }

                // Surfacing a real contradiction with the client builds trust; both genuine
                // contradictions count, ignoring them reads as a vendor who didn't read the brief.
                if (d.contradiction === `none`) {
                    trustDelta -= 9; outcomeDelta -= 4; coachKey = `coach_r1_nocontra`;
                } else {
                    trustDelta += 7;
                    if (d.design === this.TRUE_DESIGN) coachKey = `coach_r1_sharp`;
                }

                // Rigor of the outcome charter — the antidote to vague, unevaluable aspirations.
                if (d.rigor >= 60) { outcomeDelta += 7; trustDelta += 2; }
                else if (d.rigor <= 25) { outcomeDelta -= 7; coachKey = `coach_r1_vague`; }

                summaryKey = (d.design === this.TRUE_DESIGN && d.contradiction !== `none`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Architect: faculty allocation, format, application design.
                // Over-promising marquee faculty you cannot field is the headline error.
                const proposed = d.marquee;
                ds.marqueeProposed = proposed;
                ds.facultyDeliverable = Math.min(proposed, this.MARQUEE_AVAILABLE);
                const overshoot = Math.max(0, proposed - this.MARQUEE_AVAILABLE);
                // Faculty bill: marquee days are expensive (≈ €60k each across the program).
                spend += proposed * 60;

                if (overshoot > 0) {
                    ds.overPromised = true;
                    trustDelta -= (9 + overshoot * 5);    // a roster you can't deliver
                    outcomeDelta -= 3;
                    coachKey = `coach_r2_overpromise`;
                } else if (proposed === this.MARQUEE_AVAILABLE) {
                    trustDelta += 6; outcomeDelta += 7; coachKey = `coach_r2_fielded`;
                } else if (proposed >= 1) {
                    // Fewer than available but using strong practitioners where stars don't move the outcome.
                    trustDelta += 3; outcomeDelta += 3; coachKey = `coach_r2_lean`;
                } else {
                    outcomeDelta -= 5; trustDelta -= 3; coachKey = `coach_r2_nostars`;
                }

                // Format: hybrid serves "digital-first but high-touch" at a deliverable cost.
                // Format cost feeds the program P&L (margin is computed from cost vs price).
                switch (d.format) {
                    case `hybrid`: outcomeDelta += 10; trustDelta += 5; spend += 320; coachKey = (proposed === this.MARQUEE_AVAILABLE) ? `coach_r2_hybrid` : coachKey; break;
                    case `residential`: outcomeDelta += 5; trustDelta -= 5; spend += 540; coachKey = `coach_r2_residential`; break;
                    case `online`: outcomeDelta -= 30; trustDelta -= 12; spend += 230; coachKey = `coach_r2_online`; break;
                }

                // Applied design (projects, manager involvement) is where behaviour actually changes.
                if (d.application >= 50) { outcomeDelta += 9; }
                else if (d.application >= 30) { outcomeDelta += 4; }
                else { outcomeDelta -= 7; coachKey = `coach_r2_lecture`; }

                summaryKey = (overshoot === 0 && d.format === `hybrid` && d.application >= 40) ? `sum_r2_good` : (overshoot > 0 ? `sum_r2_overpromise` : `sum_r2_weak`);
            } else if (round === 3) {
                // Scope, price & defend. The chosen price sets the P&L denominator; the
                // operating margin is computed deterministically below from cost vs price.
                ds.price = d.price;

                // Pricing vs the implied ceiling and the rivals.
                if (d.price > this.PRICE_CEILING) {
                    trustDelta -= 9; coachKey = `coach_r3_overprice`;    // priced out of the bid
                } else if (d.price < 1300) {
                    coachKey = `coach_r3_underprice`;                     // buying the deal — hurts margin via the P&L
                } else {
                    trustDelta += 4;
                }

                // Procurement pressure: a 12% price cut must be matched by a 12% scope change.
                // 'descope' removes ~€150k of cost to match a price reduction; 'give' keeps the
                // full cost AND drops the price (12% off + a free third cohort) — gutting margin.
                switch (d.concession) {
                    case `descope`:
                        trustDelta += 7; coachKey = `coach_r3_descope`;
                        ds.price = Math.round(d.price * 0.88);   // accept the 12% cut...
                        spend -= 195;                            // ...matched by a real ~12% scope reduction
                        break;
                    case `hold`:
                        trustDelta -= 14; coachKey = `coach_r3_hold`;    // protects margin but the 19%-of-revenue client may walk
                        break;
                    case `give`:
                        trustDelta += 2; coachKey = `coach_r3_give`;     // gave away the year
                        ds.price = Math.round(d.price * 0.88);   // 12% off...
                        spend += 220;                            // ...plus a free third cohort, full faculty bill kept
                        break;
                }

                // On-time delivery plan against the 14-week clock.
                switch (d.delivery) {
                    case `staged`: trustDelta += 7; outcomeDelta += 4; coachKey = (d.concession === `descope`) ? `coach_r3_disciplined` : coachKey; break;
                    case `lean`: trustDelta += 1; break;
                    case `overpromise`: trustDelta -= 8; outcomeDelta -= 4; coachKey = `coach_r3_overpromise`; break;
                }

                summaryKey = (d.concession === this.TRUE_CONCESSION && d.delivery === `staged` && d.price <= this.PRICE_CEILING) ? `sum_r3_good` : (d.concession === `give` ? `sum_r3_bought` : `sum_r3_weak`);
            } else if (round === 4) {
                // Deliver & defend. Recover the cancellation without breaking the outcome map.
                switch (d.cancel) {
                    case `outcome`: outcomeDelta += 11; trustDelta += 7; spend += 40; coachKey = `coach_r4_outcome`; break;   // redesign costs a little
                    case `swap`: outcomeDelta -= 7; trustDelta -= 4; coachKey = `coach_r4_swap`; break;
                    case `cut`: outcomeDelta -= 12; trustDelta -= 5; spend -= 60; coachKey = `coach_r4_cut`; break;           // saves cost, loses two outcomes
                }

                // Re-sequence cohort two off the client's fiscal close.
                switch (d.clash) {
                    case `resequence`: trustDelta += 9; outcomeDelta += 4; coachKey = (d.cancel === `outcome`) ? `coach_r4_recovered` : coachKey; break;
                    case `push`: trustDelta -= 9; outcomeDelta -= 6; coachKey = `coach_r4_push`; break;
                }

                // Kirkpatrick: Level 3-4 behaviour evidence vs Level 1 satisfaction.
                switch (d.evidence) {
                    case `behaviour`: outcomeDelta += 11; trustDelta += 9; spend += 30; coachKey = (d.cancel === `outcome` && d.clash === `resequence`) ? `coach_r4_behaviour` : coachKey; break;
                    case `satisfaction`: outcomeDelta -= 4; trustDelta -= 4; coachKey = `coach_r4_satisfaction`; break;
                    case `none`: outcomeDelta -= 9; trustDelta -= 7; coachKey = `coach_r4_noevidence`; break;
                }

                // Conviction in defending outcomes over schedule optics.
                outcomeDelta += Math.round((d.defend - 60) / 12);
                trustDelta += Math.round((d.defend - 60) / 14);
            }

            // Resource accounting (program cost committed against the contract value).
            ds.budgetUsed = Math.max(0, Math.round(ds.budgetUsed + spend));

            // Operating margin is computed deterministically from the program P&L:
            // margin = (price - committed cost) / price. It only becomes meaningful once
            // faculty and format are committed in Round 2, so Round 1 holds the baseline 22%
            // (otherwise the overhead-only base would show an illusory spike). The textbook
            // play (overhead 700 + 3 marquee 180 + hybrid 320 = 1200 against €1,600k) lands
            // at 25%, then the R4 outcome backfill trims it toward the 22% target.
            if (round >= 2) {
                ds.margin = Math.max(-30, Math.min(60, ((ds.price - ds.budgetUsed) / ds.price) * 100));
            }

            const marginDelta = ds.margin - prevMargin;

            // Outcome and trust move on their deltas, clamped.
            ds.outcome = Math.max(0, Math.min(100, ds.outcome + outcomeDelta));
            ds.trust = Math.max(0, Math.min(100, ds.trust + trustDelta));

            ds.marginHistory.push(Math.round(ds.margin));
            ds.outcomeHistory.push(Math.round(ds.outcome));
            ds.trustHistory.push(Math.round(ds.trust));

            if (round === this.ROUNDS.length && ds.margin < this.TARGET_MARGIN) ds.marginMissed = true;

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                margin: Math.round(ds.margin),
                marginDelta: Math.round(marginDelta),
                outcome: Math.round(ds.outcome),
                outcomeDelta: Math.round(outcomeDelta),
                trust: Math.round(ds.trust),
                trustDelta: Math.round(trustDelta),
                facultyDeliverable: ds.facultyDeliverable,
                marqueeProposed: ds.marqueeProposed,
                budgetUsed: ds.budgetUsed,
                overPromised: ds.overPromised,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

