        // Pure helper: 0–100 score for how healthy the operating margin is.
        // Full marks across the 22–32% band; falls off below the 22% target (0 at the
        // value-destroying floor) and decays above 32% (over-cheap = under-invested program).
        _marginBandScore(margin) {
            if (margin >= this.TARGET_MARGIN && margin <= 32) return 100;
            if (margin > 32) return Math.max(60, 100 - (margin - 32) * 2.5);
            if (margin <= this.MARGIN_FLOOR) return 0;
            // Linear from 0 at the floor to 100 at the target.
            return ((margin - this.MARGIN_FLOOR) / (this.TARGET_MARGIN - this.MARGIN_FLOOR)) * 100;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const margin = Math.round(ds.margin);
            const outcome = Math.round(ds.outcome);
            const trust = Math.round(ds.trust);

            const hitMargin = margin >= this.TARGET_MARGIN;
            const valueDestroying = margin < this.MARGIN_FLOOR;
            const strongOutcome = outcome >= 60;
            const keptClient = trust >= 60;
            const overPromised = ds.overPromised;
            // Margin sub-score is a BAND, not "more is better": a custom program should land in
            // the healthy 22–32% band. Below target it falls off fast; a suspiciously fat margin
            // (>32%) means the program was under-invested — under-delivery dressed as profit — so
            // it is rewarded LESS than an on-target program, never more.
            const marginScore = this._marginBandScore(margin);
            const composite = Math.round(
                marginScore * 0.30 +
                outcome * 0.35 +
                trust * 0.35
            );

            let performanceKey = `lost_bid`;
            if (hitMargin && strongOutcome && keptClient && composite >= 72) performanceKey = `flagship`;
            else if (hitMargin && strongOutcome && keptClient) performanceKey = `won_deliverable`;
            else if (!valueDestroying && strongOutcome && keptClient) performanceKey = `won_thin`;
            else if (overPromised) performanceKey = `overpromised`;
            else if (valueDestroying) performanceKey = `bought`;
            else if (outcome < 45) performanceKey = `no_impact`;
            // Stable, language-independent tier handle for the grading/reporting layer (read from domainState).
            ds.performanceTier = performanceKey;
            // Localized label for the debrief overlay (fixes English label leaking on non-EN screens).
            const performance = window.mySimulation.t(`tier_` + performanceKey);

            const insights = [];
            if (hitMargin && strongOutcome && keptClient) insights.push(window.mySimulation.t(`insight_flagship`));
            else if (valueDestroying) insights.push(window.mySimulation.t(`insight_bought`));
            else if (overPromised) insights.push(window.mySimulation.t(`insight_overpromise`));
            else if (outcome < 45) insights.push(window.mySimulation.t(`insight_noimpact`));
            else insights.push(window.mySimulation.t(`insight_mixed`));

            if (!hitMargin && !valueDestroying) insights.push(window.mySimulation.t(`insight_marginshort`));
            if (trust < 45) insights.push(window.mySimulation.t(`insight_lowtrust`));
            if (outcome >= 75 && trust >= 70) insights.push(window.mySimulation.t(`insight_reference`));
            if (hitMargin && strongOutcome && keptClient && composite >= 80) insights.push(window.mySimulation.t(`insight_renewal`));

            return {
                margin: margin,
                outcome: outcome,
                trust: trust,
                hitMargin: hitMargin,
                valueDestroying: valueDestroying,
                overPromised: overPromised,
                composite: composite,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.overPromised) return window.mySimulation.t(`hint_overpromise`);
            if (ds.margin < this.MARGIN_FLOOR) return window.mySimulation.t(`hint_margin`);
            if (ds.outcome < 35) return window.mySimulation.t(`hint_outcome`);
            if (state.currentPeriod >= 3 && ds.trust < 45) return window.mySimulation.t(`hint_trust`);
            if (ds.margin >= this.TARGET_MARGIN && ds.outcome >= 60 && ds.trust >= 60) return window.mySimulation.t(`hint_strong`);
            return null;
        }

